sp_widget.css:
/* Estilo para o container principal */
.clp-container {
    // Garantindo a família da fonte para todo o bloco
    font-family: 'Roboto', sans-serif;
    text-align: center;
    // Removendo margens/padding desnecessários
    line-height: 1; 
    padding: 60px 0; // Padding vertical para dar espaço
}

/* Estilos para o texto normal */
.clp-normal-text {
    font-weight: 500; // Medium
    font-size: 24px;
    color: #4773C6;
    // O line-height 100% e letter-spacing 0% já são o padrão na maioria dos casos, mas mantemos por precisão.
}

/* Estilos para o texto em negrito */
.clp-bold-text {
    font-weight: 700; // Bold
    font-size: 24px;
    color: #4773C6;
}

/* Estilos para o link "Clique aqui." */
.clp-link {
    font-weight: 400; // Regular
    font-size: 22px;
    color: #1D357F; // Cor específica do link
    text-decoration: underline;
    cursor: pointer; 

    // Animação de transição de 0.3 segundos para a cor
    transition: color 0.3s ease; 
}

/* Efeito de HOVER: O link muda para um azul mais escuro suavemente */
.clp-link:hover {
    color: #16295c; // Um azul ligeiramente mais escuro que #1D357F
}

sp_widget.script:
(function() {
    /* define o URL de destino do link */
    data.link_url = options.clp_link_url || "https://rankingdecompetitividade.org.br/"; 
})();
